// Two-scan pairing on the web: the kind-21195 hello/ack wrapper (pair-hello.js) and the paired-device store
// (pair-devices.js). Throwaway keys only: every key here is generated by the test.
import { test } from "node:test"
import assert from "node:assert/strict"
import { generateSecretKey, getPublicKey, finalizeEvent } from "nostr-tools/pure"
import { bytesToHex } from "nostr-tools/utils"
import { npubEncode } from "nostr-tools/nip19"
import { sealHello, openHello, ownMeshHex, sendHello, listenHellos } from "../src/net/pair-hello.js"
import { pairedDevices, addPaired, roleCheckList, ownersForAccount } from "../src/net/pair-devices.js"
import { HELLO_KIND, helloJson, roleCheck } from "../src/net/mesh-pairing.js"

const memStorage = () => {
  const m = new Map()
  return { getItem: k => (m.has(k) ? m.get(k) : null), setItem: (k, v) => m.set(k, String(v)), removeItem: k => m.delete(k), get map() { return m } }
}
const keypair = () => { const sk = generateSecretKey(); return { sk, hex: getPublicKey(sk) } }

test("a hello seals to the other mesh key and opens only there", async () => {
  const a = keypair(), b = keypair(), c = keypair()
  const content = helloJson({ s: "AAAAAAAAAAAAAAAAAAAAAA", n: "Chrome on Mac", r: "browser", o: npubEncode(c.hex), t: 1000 })
  const ev = await sealHello({ toHex: a.hex, content, now: 1000, sk: b.sk })
  assert.equal(ev.kind, HELLO_KIND)
  assert.equal(ev.pubkey, b.hex)
  assert.deepEqual(ev.tags, [["p", a.hex]])
  assert.ok(!ev.content.includes("Chrome"), "content is encrypted")
  assert.deepEqual(await openHello(ev, { ownHex: a.hex, sk: a.sk }), { sender: b.hex, content })
  // Not to me, a wrong key, a tampered event, another kind: all null.
  assert.equal(await openHello(ev, { ownHex: c.hex, sk: c.sk }), null)
  assert.equal(await openHello({ ...ev, content: ev.content.slice(0, -4) + "AAAA" }, { ownHex: a.hex, sk: a.sk }), null)
  assert.equal(await openHello({ ...ev, created_at: 1001 }, { ownHex: a.hex, sk: a.sk }), null)
  const other = finalizeEvent({ kind: 1, created_at: 1000, tags: [["p", a.hex]], content: ev.content }, b.sk)
  assert.equal(await openHello(other, { ownHex: a.hex, sk: a.sk }), null)
  // verifyEvent's cached flag on the object is not trusted.
  const forged = { ...ev, pubkey: c.hex }
  forged[Symbol.for("verified")] = true
  assert.equal(await openHello(forged, { ownHex: a.hex, sk: a.sk }), null)
  // Two p tags: not a hello to me.
  const twoP = finalizeEvent({ kind: HELLO_KIND, created_at: 1000, tags: [["p", a.hex], ["p", c.hex]], content: ev.content }, b.sk)
  assert.equal(await openHello(twoP, { ownHex: a.hex, sk: a.sk }), null)
})

test("sealing refuses a bad address", async () => {
  await assert.rejects(sealHello({ toHex: "npub1xyz", content: "{}", sk: keypair().sk }))
})

test("the browser's mesh key is the FIPS key, made when missing and read per call", async () => {
  const s = memStorage()
  const hex = await ownMeshHex(s)
  assert.match(hex, /^[0-9a-f]{64}$/)
  const stored = s.getItem("nv-vault:fips-relay-key")
  assert.match(stored, /^[0-9a-f]{64}$/)
  assert.equal(await ownMeshHex(s), hex, "same key the next time")
  // A hello sealed with the stored key opens on the other side and is from that address.
  const a = keypair()
  const ev = await sealHello({ toHex: a.hex, content: "hi", storage: s, now: 5 })
  assert.equal(ev.pubkey, hex)
  assert.equal((await openHello(ev, { ownHex: a.hex, sk: a.sk })).content, "hi")
  // And one to the browser opens with the stored key.
  const back = await sealHello({ toHex: hex, content: "back", sk: a.sk, now: 6 })
  assert.deepEqual(await openHello(back, { ownHex: hex, storage: s }), { sender: a.hex, content: "back" })
})

test("send counts the relays that took the event; a resend is the same event", async () => {
  const sent = []
  const ev = { id: "x" }
  const n = await sendHello(ev, { relays: ["wss://a", "wss://b", "wss://c"], publish: (r, e) => { sent.push(e); return [Promise.resolve(), Promise.reject(new Error("no")), Promise.resolve()] } })
  assert.equal(n, 2)
  assert.equal(sent[0], ev)
})

test("listen asks for kind 21195 to this address and passes each event once", () => {
  let filter, handlers, closed = false
  const got = []
  const close = listenHellos("ab".repeat(32), ev => got.push(ev.id), {
    relays: ["wss://a"], since: 77,
    subscribe: (r, f, h) => { filter = f; handlers = h; return { close: () => { closed = true } } },
  })
  assert.deepEqual(filter, { kinds: [HELLO_KIND], "#p": ["ab".repeat(32)], since: 77 })
  handlers.onevent({ id: "1" }); handlers.onevent({ id: "1" }); handlers.onevent({ id: "2" })
  assert.deepEqual(got, ["1", "2"])
  close()
  assert.ok(closed)
})

test("linking adds the device to the owner set, the live set and its name/role record", () => {
  const s = memStorage()
  const old = keypair().hex
  s.setItem("nv-vault:fips-owners", old) // paired by link before: no role on record
  const dev = keypair()
  const live = new Set([old])
  const list = addPaired({ npub: npubEncode(dev.hex), name: "Logen's iPhone", role: "phone" }, { storage: s, liveOwners: live })
  assert.ok(live.has(dev.hex))
  assert.deepEqual(new Set(s.getItem("nv-vault:fips-owners").split(" ")), new Set([old, dev.hex]))
  assert.deepEqual(list.find(d => d.hex === dev.hex), { hex: dev.hex, npub: npubEncode(dev.hex), name: "Logen's iPhone", role: "phone" })
  assert.equal(list.find(d => d.hex === old).role, null)
  assert.deepEqual(pairedDevices(s), list)
})

test("role check: same role is already linked, another role is refused, a link-paired device is already linked", () => {
  const s = memStorage()
  const phone = keypair().hex, legacy = keypair().hex
  s.setItem("nv-vault:fips-owners", legacy)
  addPaired({ npub: npubEncode(phone), name: "P", role: "phone" }, { storage: s })
  const devs = pairedDevices(s)
  assert.equal(roleCheck(npubEncode(phone), "phone", roleCheckList(devs, "phone")), "alreadyLinked")
  assert.equal(roleCheck(npubEncode(phone), "homeVault", roleCheckList(devs, "homeVault")), "refuseOtherRole:phone")
  assert.equal(roleCheck(npubEncode(legacy), "mac", roleCheckList(devs, "mac")), "alreadyLinked")
  assert.equal(roleCheck(npubEncode(keypair().hex), "mac", roleCheckList(devs, "mac")), "add")
})

test("nothing in the store before a link; bad stored data reads as empty", () => {
  const s = memStorage()
  assert.deepEqual(pairedDevices(s), [])
  s.setItem("nv-vault:fips-owner-meta", "{not json")
  s.setItem("nv-vault:fips-owners", bytesToHex(new Uint8Array(32)).replace(/^00/, "zz"))
  assert.deepEqual(pairedDevices(s), [])
})

test("sign-out forgets the paired devices: the owner set, their names and roles, and the mesh key (Tron, PR 1705)", async () => {
  const { forgetThisBrowser } = await import("../src/haven/vault.js")
  const s = memStorage()
  await ownMeshHex(s)
  addPaired({ npub: npubEncode(keypair().hex), name: "Alice's iPhone", role: "phone" }, { storage: s })
  s.setItem("unrelated", "keep")
  const idb = { deleteDatabase() { const req = {}; setTimeout(() => req.onsuccess?.()); return req }, databases: async () => [] }
  const { failed } = await forgetThisBrowser({ vault: null, pubkey: "e".repeat(64), storage: s, idb, waitMs: 50, session: memStorage(), sw: {} })
  assert.deepEqual(failed, [])
  assert.deepEqual([...s.map.keys()], ["unrelated"])
  assert.deepEqual(pairedDevices(s), [])
})

test("paired devices are per account: another account's device is not this one's owner (Tron 20)", () => {
  const s = memStorage()
  const A = keypair().hex, B = keypair().hex
  s.setItem("nv-accounts", JSON.stringify([{ method: "readonly", pubkey: A }, { method: "readonly", pubkey: B }]))
  const link = keypair().hex
  s.setItem("nv-vault:fips-owners", link) // paired by link before: everyone's, as before
  const phoneA = keypair().hex, macB = keypair().hex
  addPaired({ npub: npubEncode(phoneA), name: "A's iPhone", role: "phone" }, { storage: s, pubkey: A })
  addPaired({ npub: npubEncode(macB), name: "B's Mac", role: "mac" }, { storage: s, pubkey: B })
  assert.deepEqual(new Set(pairedDevices(s, A).map(d => d.hex)), new Set([link, phoneA]))
  assert.deepEqual(new Set(pairedDevices(s, B).map(d => d.hex)), new Set([link, macB]))
  const saved = new Set(s.getItem("nv-vault:fips-owners").split(" "))
  assert.deepEqual(ownersForAccount(saved, A, { storage: s }), new Set([link, phoneA]))
  assert.deepEqual(ownersForAccount(saved, B, { storage: s }), new Set([link, macB]))
  // Each account's record ends in its pubkey, so signing that account out removes it (vault.js accountKeys).
  assert.ok(s.getItem(`nv-vault:fips-paired:${A}`).includes(phoneA))
})

test("the one-per-browser list from before moves to the account that reads it first", () => {
  const s = memStorage()
  const A = keypair().hex, dev = keypair().hex
  s.setItem("nv-vault:fips-owners", dev)
  s.setItem("nv-vault:fips-owner-meta", JSON.stringify({ [dev]: { name: "Old", role: "mac" } }))
  assert.deepEqual(pairedDevices(s, A).map(d => [d.name, d.role]), [["Old", "mac"]])
  assert.equal(s.getItem("nv-vault:fips-owner-meta"), null)
  assert.ok(s.getItem(`nv-vault:fips-paired:${A}`).includes("Old"))
})

test("an owner list that can't be read is not overwritten by a new link", () => {
  const s = memStorage()
  s.setItem("nv-vault:fips-owners", "not-a-key")
  assert.throws(() => addPaired({ npub: npubEncode(keypair().hex), name: "x", role: "phone" }, { storage: s, pubkey: keypair().hex }), /can't be read/)
  assert.equal(s.getItem("nv-vault:fips-owners"), "not-a-key")
})
